// Method: SkeletonProfile::set_reference_pose
static JSValue js_SkeletonProfile_set_reference_pose(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "SkeletonProfile.set_reference_pose: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "SkeletonProfile.set_reference_pose: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "SkeletonProfile.set_reference_pose: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "SkeletonProfile.set_reference_pose: invalid or freed object");
    }

    SkeletonProfile* typed_obj = Object::cast_to<SkeletonProfile>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "SkeletonProfile.set_reference_pose: object is not a SkeletonProfile");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 3) {
        return JS_ThrowTypeError(ctx, "SkeletonProfile.set_reference_pose: expected at least 2 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t arg_bone_idx; JS_ToInt64(ctx, &arg_bone_idx, argv[1]);
    Transform3D arg_bone_name;
    JSValue jbasis_bone_name = JS_GetPropertyStr(ctx, argv[2], "basis");
    JSValue jorigin_bone_name = JS_GetPropertyStr(ctx, argv[2], "origin");
    if (!JS_IsUndefined(jorigin_bone_name)) {
        double ox, oy, oz;
        JSValue jox_bone_name = JS_GetPropertyStr(ctx, jorigin_bone_name, "x");
        JSValue joy_bone_name = JS_GetPropertyStr(ctx, jorigin_bone_name, "y");
        JSValue joz_bone_name = JS_GetPropertyStr(ctx, jorigin_bone_name, "z");
        JS_ToFloat64(ctx, &ox, jox_bone_name);
        JS_ToFloat64(ctx, &oy, joy_bone_name);
        JS_ToFloat64(ctx, &oz, joz_bone_name);
        arg_bone_name.origin = Vector3(ox, oy, oz);
        JS_FreeValue(ctx, jox_bone_name); JS_FreeValue(ctx, joy_bone_name); JS_FreeValue(ctx, joz_bone_name);
    }
    if (!JS_IsUndefined(jbasis_bone_name)) {
        JSValue jbx_bone_name = JS_GetPropertyStr(ctx, jbasis_bone_name, "x");
        JSValue jby_bone_name = JS_GetPropertyStr(ctx, jbasis_bone_name, "y");
        JSValue jbz_bone_name = JS_GetPropertyStr(ctx, jbasis_bone_name, "z");
        if (!JS_IsUndefined(jbx_bone_name) && !JS_IsUndefined(jby_bone_name) && !JS_IsUndefined(jbz_bone_name)) {
            double xx, xy, xz, yx, yy, yz, zx, zy, zz;
            JSValue jbxx = JS_GetPropertyStr(ctx, jbx_bone_name, "x"); JSValue jbxy = JS_GetPropertyStr(ctx, jbx_bone_name, "y"); JSValue jbxz = JS_GetPropertyStr(ctx, jbx_bone_name, "z");
            JSValue jbyx = JS_GetPropertyStr(ctx, jby_bone_name, "x"); JSValue jbyy = JS_GetPropertyStr(ctx, jby_bone_name, "y"); JSValue jbyz = JS_GetPropertyStr(ctx, jby_bone_name, "z");
            JSValue jbzx = JS_GetPropertyStr(ctx, jbz_bone_name, "x"); JSValue jbzy = JS_GetPropertyStr(ctx, jbz_bone_name, "y"); JSValue jbzz = JS_GetPropertyStr(ctx, jbz_bone_name, "z");
            JS_ToFloat64(ctx, &xx, jbxx); JS_ToFloat64(ctx, &xy, jbxy); JS_ToFloat64(ctx, &xz, jbxz);
            JS_ToFloat64(ctx, &yx, jbyx); JS_ToFloat64(ctx, &yy, jbyy); JS_ToFloat64(ctx, &yz, jbyz);
            JS_ToFloat64(ctx, &zx, jbzx); JS_ToFloat64(ctx, &zy, jbzy); JS_ToFloat64(ctx, &zz, jbzz);
            arg_bone_name.basis = Basis(Vector3(xx, xy, xz), Vector3(yx, yy, yz), Vector3(zx, zy, zz));
            JS_FreeValue(ctx, jbxx); JS_FreeValue(ctx, jbxy); JS_FreeValue(ctx, jbxz);
            JS_FreeValue(ctx, jbyx); JS_FreeValue(ctx, jbyy); JS_FreeValue(ctx, jbyz);
            JS_FreeValue(ctx, jbzx); JS_FreeValue(ctx, jbzy); JS_FreeValue(ctx, jbzz);
        }
        JS_FreeValue(ctx, jbx_bone_name); JS_FreeValue(ctx, jby_bone_name); JS_FreeValue(ctx, jbz_bone_name);
    }
    JS_FreeValue(ctx, jbasis_bone_name);
    JS_FreeValue(ctx, jorigin_bone_name);

    typed_obj->set_reference_pose(arg_bone_idx, arg_bone_name);
    return JS_UNDEFINED;
}

